      "desc": "🫧 忘却的代价，永远大于记忆的代价。 欢迎来到《知行小酒馆》，这是一档由有知有行出品的播客节目，我们关注投资，更关注怎样更好地生活。我是雨白。 一个多月前，我和家里长辈闲聊，她突然特别严肃地问我： “你知道吗？那个谁谁谁说，今年年底会发生一场全球性的金融危机，规模堪比 2008 年” ，我非常惊讶，问她是从哪里听说的，结果聊了半天，她也没说清楚这个人到底是干嘛的，更不知道他怎么推导出金融危机这个结论。这件事让我印象很深。 我讲这个故事，不是为了奚落家里人。因为我们大部分人面对财经信息的时候，可能都是这个状态。 每天，我们的心情会被各种消息来回拉扯：一会儿怕错过泡沫，一会儿又怕危机真的来了。太",
