      "desc": "主播 | 刘飞 潇磊 有些互联网产品，我们每天都在用，却很少对它们产生感情；还有一些网站，可能已经很久没有打开，却始终像一间时时想念的旧房间。 豆瓣、知乎、贴吧、虎扑，曾经承载了文艺青年、知识分子、追星族、游戏玩家和无数小众爱好者的日常交流。它们拥有最忠诚的用户、最独特的文化，也创造过许多影响至今的内容和网络语言。可奇怪的是，这些最像「精神家园」的社区，往往也是互联网行业里最难赚钱的一批公司。 到底是时代辜负了它们，还是社区从诞生的那一天起，就埋下了自己的难题？ 这一期，我们回到中文互联网曾经最热闹、也最有人情味的几个角落。 来杯半拿铁，咱们边喝边唠。 — 潇磊、刘飞的声音已授权给豆包、剪映等",
      "pub": "Wed, 29 Jul 2026 20:00:00 +0800",
